667	func replaceFirst(haystack, marker, replacement []byte) []byte {
668		i := indexBytes(haystack, marker)
669		if i < 0 {
670			return haystack
671		}
672		out := append([]byte(nil), haystack[:i]...)
673		out = append(out, replacement...)
674		out = append(out, haystack[i+len(marker):]...)
675		return out
676	}
677	
678	func indexBytes(haystack, needle []byte) int {
679		for i := 0; i+len(needle) <= len(haystack); i++ {
680			if string(haystack[i:i+len(needle)]) == string(needle) {
681				return i
682			}
683		}
684		return -1
685	}
