687	// Concurrent import vs freeze must leave only a complete definition (old or
688	// new), never a frozen version with a half-applied or missing definition,
689	// and the on-disk state must reopen consistently.
690	func TestImportFreezeRaceCompleteness(t *testing.T) {
691		for iter := 0; iter < 20; iter++ {
692			dir := t.TempDir()
693			s, _ := Open(dir)
694			seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
695	
696			alt := `{"modulus":"7","constraints":[
697				{"a":[{"wire":1,"coeff":"3"}],"b":[],"c":[]}]}`
698			altPath := writeTempJSON(t, alt)
699	
700			var wg sync.WaitGroup
701			start := make(chan struct{})
702			wg.Add(2)
703			go func() {
704				defer wg.Done()
705				<-start
706				for range 200 {
707					if _, err := s.ImportConstraints("c", 1, altPath); err != nil {
708						if !errors.Is(err, ErrFrozen) {
709							t.Errorf("unexpected import error: %v", err)
710						}
711						return
712					}
713				}
714			}()
715			go func() {
716				defer wg.Done()
717				<-start
718				s.FreezeCircuit("c", 1)
719			}()
720			close(start)
721			wg.Wait()
722	
723			c, err := s.GetCircuit("c", 1)
724			if err != nil {
725				t.Fatal(err)
726			}
727			if !c.Frozen {
728				t.Fatalf("iter %d: version not frozen", iter)
729			}
730			def, err := s.GetDefinition("c", 1)
731			if err != nil {
732				t.Fatalf("iter %d: frozen version must keep a complete definition: %v", iter, err)
733			}
734			// Every import of the same alt content is byte-identical, and the
735			// original is fully distinct: a mixed body is impossible. Just check
736			// the modulus is coherent and it recompiles to a stable hash.
737			a1, err := s.CompileCircuit("c", 1)
738			if err != nil {
739				t.Fatalf("iter %d: compile after race: %v", iter, err)
740			}
741			a2, _ := s.CompileCircuit("c", 1)
742			if a1 != a2 {
743				t.Fatalf("iter %d: artifact not stable: %+v %+v", iter, a1, a2)
744			}
745			if len(def.Constraints) != 1 {
746				t.Fatalf("iter %d: bad definition %+v", iter, def)
747			}
748			s.Close()
749	
750			s2, err := Open(dir)
751			if err != nil {
752				t.Fatalf("iter %d: reopen: %v", iter, err)
753			}
754			got, err := s2.GetArtifact("c", 1)
755			s2.Close()
756			if err != nil || got != a1 {
757				t.Fatalf("iter %d: reopened artifact mismatch: %+v %v", iter, got, err)
758			}
759		}
760	}
