package zkcircuit

import (
	"math/big"
	"testing"
)

// This file is an arithmetic regression guard for input checking. The
// pre-existing max-modulus test only multiplied two small single-term values;
// these cases exercise multi-term linear combinations (constant wire 0, public
// and private inputs together) at the largest legal prime 2147483647, where
// coefficients and inputs sit close to the modulus and the unreduced products
// and linear-combination sums exceed the int32 range. They also pin down the
// "first failing constraint only" semantics and the meaning of repeated wires
// and cancelling coefficients.

const regressionMaxPrime = "2147483647"

// regressionCircuit creates a draft, imports def, freezes and compiles it,
// returning the store and the compiled artifact. The check is always bound to
// the artifact's own hash, the only public way a check can run.
func regressionCircuit(t *testing.T, name string, version, pub, priv int, def string) (*Store, Artifact) {
	t.Helper()
	s := openTestStore(t)
	count := countConstraintsInDef(t, def)
	if _, err := s.CreateCircuit(Circuit{Name: name, Version: version, Constraints: count,
		PublicInputs: pub, PrivateInputs: priv, Description: name}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ImportConstraints(name, version, writeTempJSON(t, def)); err != nil {
		t.Fatalf("import: %v", err)
	}
	if _, err := s.FreezeCircuit(name, version); err != nil {
		t.Fatal(err)
	}
	artifact, err := s.CompileCircuit(name, version)
	if err != nil {
		t.Fatalf("compile: %v", err)
	}
	return s, artifact
}

// countConstraintsInDef extracts the constraint count through the real parser
// so a definition edit cannot silently drift from the declared count.
func countConstraintsInDef(t *testing.T, def string) int {
	t.Helper()
	d, err := parseDefinitionJSON([]byte(def), 0, 0, 99)
	if err != nil {
		t.Fatalf("parse definition for count: %v", err)
	}
	return len(d.constraints)
}

// assertSatisfied and assertUnsatisfied pin the complete verdict contract:
// a check that completes (satisfiable or not) is never a call failure, the
// verdict carries only the conclusion, the bound hash (echoing the request)
// and the 1-based first-failure index.
func assertSatisfied(t *testing.T, s *Store, name string, version int, hash string, w Witness) {
	t.Helper()
	res, err := s.CheckInput(name, version, hash, w)
	if err != nil {
		t.Fatalf("satisfying check returned a call error: %v", err)
	}
	if !res.Satisfied || res.FirstFailure != 0 {
		t.Fatalf("want satisfied with first_failure=0, got %+v", res)
	}
	if res.Hash != hash {
		t.Fatalf("bound hash %q does not match request %q", res.Hash, hash)
	}
}

func assertUnsatisfied(t *testing.T, s *Store, name string, version int, hash string, w Witness, wantFailure int) {
	t.Helper()
	res, err := s.CheckInput(name, version, hash, w)
	if err != nil {
		t.Fatalf("an unsatisfied constraint is a completed check, not a call error: %v", err)
	}
	if res.Satisfied {
		t.Fatalf("want unsatisfied, got %+v", res)
	}
	if res.FirstFailure != wantFailure {
		t.Fatalf("want first_failure=%d, got %+v", wantFailure, res)
	}
	if res.Hash != hash {
		t.Fatalf("bound hash %q does not match request %q", res.Hash, hash)
	}
}

// TestMaxPrimeMultiTermNoOverflow is the central regression the old coverage
// could not catch. The single constraint mixes wire 0 (constant 1), a public
// input and a private input on every side, with coefficients and input values
// all close to p = 2147483647:
//
//	a = (p-1)·1 + (p-2)·x
//	b = (p-3)·1 + (p-4)·y
//	c = 106·1  + (p-7)·x + (p-8)·y
//
// For x = p-5, y = p-6 the integer a,b are 9,21 mod p and a·b = 189 = c
// mod p. Before reduction a and the individual products (p-2)·(p-5) and
// (p-4)·(p-6) are ~4.61·10^18, above the int32 maximum; an evaluator that
// used 32-bit arithmetic (or any overflowing accumulation) would draw the
// wrong conclusion here.
func TestMaxPrimeMultiTermNoOverflow(t *testing.T) {
	def := `{"modulus":"` + regressionMaxPrime + `","constraints":[
		{"a":[{"wire":0,"coeff":"2147483646"},{"wire":1,"coeff":"2147483645"}],
		 "b":[{"wire":0,"coeff":"2147483644"},{"wire":2,"coeff":"2147483643"}],
		 "c":[{"wire":0,"coeff":"106"},{"wire":1,"coeff":"2147483640"},{"wire":2,"coeff":"2147483639"}]}]}`
	s, artifact := regressionCircuit(t, "big", 1, 1, 1, def)

	// Guard the premise of the test: intermediate integer magnitudes really
	// do exceed int32, so a 32-bit-overflow evaluator would be exposed.
	p := big.NewInt(2147483647)
	termProduct := new(big.Int).Mul(big.NewInt(2147483645), big.NewInt(2147483642)) // (p-2)(p-5)
	linearSum := new(big.Int).Add(big.NewInt(2147483646), termProduct)              // (p-1)+(p-2)(p-5)
	int32Max := big.NewInt(2147483647)
	if termProduct.Cmp(int32Max) <= 0 || linearSum.Cmp(int32Max) <= 0 {
		t.Fatalf("test premise lost: products/sums must exceed int32, got %s, %s", termProduct, linearSum)
	}
	// And they stay inside int64, which is the implementation's own
	// exactness guarantee: this case must be decided by modular reduction,
	// not by big-int fallback masking a narrower type.
	int64Max, _ := new(big.Int).SetString("9223372036854775807", 10)
	if termProduct.Cmp(int64Max) > 0 || linearSum.Cmp(int64Max) > 0 {
		t.Fatalf("test values leave the int64 range the evaluator relies on")
	}

	good := Witness{Public: []string{"2147483642"}, Private: []string{"2147483641"}} // x=p-5, y=p-6
	assertSatisfied(t, s, "big", 1, artifact.Hash, good)

	// Same reduced assignment expressed with a negative private value
	// (-7 ≡ p-6 mod p): decimal-string rules interpret it modulo the field.
	neg := Witness{Public: []string{"2147483642"}, Private: []string{"-7"}}
	assertSatisfied(t, s, "big", 1, artifact.Hash, neg)

	// Changing one input breaks the equation: y = p-7 makes a·b ≡ 225 while
	// c ≡ 197 mod p. This must read unsatisfied, never "satisfied by overflow".
	bad := Witness{Public: []string{"2147483642"}, Private: []string{"2147483640"}}
	assertUnsatisfied(t, s, "big", 1, artifact.Hash, bad, 1)

	// Changing the public input instead must likewise fail.
	badPub := Witness{Public: []string{"2147483641"}, Private: []string{"2147483641"}}
	assertUnsatisfied(t, s, "big", 1, artifact.Hash, badPub, 1)

	// Prove the satisfying witness genuinely depends on all three wire
	// kinds rather than on vacuous sides: zeroing both inputs must not
	// satisfy (a would be p-1, b would be p-3, c would be 106).
	zero := Witness{Public: []string{"0"}, Private: []string{"0"}}
	assertUnsatisfied(t, s, "big", 1, artifact.Hash, zero, 1)
}

// TestMaxPrimeFirstFailureOrdering pins the meaning of "only the first
// failing constraint is reported". One frozen version carries three
// constraints in definition order; the witness is chosen so that each of the
// following scenarios points at the constraint that actually fails first:
//
//	wires: w1,w2 public = 5,4 ; w3,w4,w5 private = 7,2,29
//	C1: ((p-1) + 2·w1)·(1 + 3·w3) = 198
//	C2: (1 + 2·w2)·((p-1) + 3·w4) = 45
//	C3: (1 + w5)·1 = 30
//
// Every side is a genuine multi-term linear combination and the products run
// into the 10^18 range at p = 2147483647.
func TestMaxPrimeFirstFailureOrdering(t *testing.T) {
	def := `{"modulus":"` + regressionMaxPrime + `","constraints":[
		{"a":[{"wire":0,"coeff":"-1"},{"wire":1,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"1"},{"wire":3,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"198"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":2,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"-1"},{"wire":4,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"45"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":5,"coeff":"1"}],
		 "b":[{"wire":0,"coeff":"1"}],
		 "c":[{"wire":0,"coeff":"30"}]}]}`
	s, artifact := regressionCircuit(t, "ord", 1, 2, 3, def)

	// Baseline: everything holds; first_failure is 0.
	base := Witness{Public: []string{"5", "4"}, Private: []string{"7", "2", "29"}}
	assertSatisfied(t, s, "ord", 1, artifact.Hash, base)

	// Earlier constraints hold, a later one fails: the result points at the
	// later constraint's real position.
	onlyC3 := Witness{Public: []string{"5", "4"}, Private: []string{"7", "2", "100"}}
	assertUnsatisfied(t, s, "ord", 1, artifact.Hash, onlyC3, 3)

	onlyC2 := Witness{Public: []string{"5", "4"}, Private: []string{"7", "8", "29"}}
	assertUnsatisfied(t, s, "ord", 1, artifact.Hash, onlyC2, 2)

	// Several constraints fail at once: the earliest failing one wins. Here
	// the public value w2=10 breaks both C2 and C3 but C1 still holds.
	c2AndC3 := Witness{Public: []string{"5", "10"}, Private: []string{"7", "2", "29"}}
	assertUnsatisfied(t, s, "ord", 1, artifact.Hash, c2AndC3, 2)

	// The first constraint failing must hide every later failure.
	c1First := Witness{Public: []string{"6", "10"}, Private: []string{"7", "2", "29"}}
	assertUnsatisfied(t, s, "ord", 1, artifact.Hash, c1First, 1)
}

// TestMaxPrimeCongruentRepresentationsAgree checks that, against one frozen
// definition, replacing inputs with other legal decimal representations that
// differ by an integer multiple of the modulus leaves both the satisfaction
// state and the first-failure position unchanged. The alternatives are
// negative and far longer than machine integers.
func TestMaxPrimeCongruentRepresentationsAgree(t *testing.T) {
	// Reuse the ordering circuit: it has multiple constraints so the
	// first-failure index is meaningful in the unsatisfied variants too.
	def := `{"modulus":"` + regressionMaxPrime + `","constraints":[
		{"a":[{"wire":0,"coeff":"-1"},{"wire":1,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"1"},{"wire":3,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"198"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":2,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"-1"},{"wire":4,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"45"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":5,"coeff":"1"}],
		 "b":[{"wire":0,"coeff":"1"}],
		 "c":[{"wire":0,"coeff":"30"}]}]}`
	s, artifact := regressionCircuit(t, "cong", 1, 2, 3, def)

	// Satisfying family: (5,4,7,2,29) rewritten with values congruent mod p.
	// x_big = (p-5) + p·10^24 happens to equal 5's family-mate only after
	// reduction... here each listed value is congruent to the corresponding
	// base value: 5 + p·10^20, 4 - p·10^12, 7 + p, 2 - 2p, 29 + p·10^8.
	cases := []Witness{
		{Public: []string{"5", "4"}, Private: []string{"7", "2", "29"}},
		{
			Public: []string{
				new(big.Int).Add(big.NewInt(5), new(big.Int).Mul(pow10(20), bigIntP())).String(),
				new(big.Int).Sub(big.NewInt(4), new(big.Int).Mul(pow10(12), bigIntP())).String(),
			},
			Private: []string{
				new(big.Int).Add(big.NewInt(7), bigIntP()).String(),
				new(big.Int).Sub(big.NewInt(2), new(big.Int).Add(bigIntP(), bigIntP())).String(),
				new(big.Int).Add(big.NewInt(29), new(big.Int).Mul(pow10(8), bigIntP())).String(),
			},
		},
	}
	for i, w := range cases {
		res, err := s.CheckInput("cong", 1, artifact.Hash, w)
		if err != nil {
			t.Fatalf("satisfying case %d: %v", i, err)
		}
		if !res.Satisfied || res.FirstFailure != 0 || res.Hash != artifact.Hash {
			t.Fatalf("congruent satisfying case %d changed the verdict: %+v", i, res)
		}
	}

	// Unsatisfying family: the base (5,4,7,8,29) fails at C2. Two
	// congruent rewrites (one 40-digit positive, one huge negative) must
	// keep the identical first-failure position.
	unsat := []Witness{
		{Public: []string{"5", "4"}, Private: []string{"7", "8", "29"}},
		{ // y4 = (p-7+... ) must equal 8 + kp; use 8 + p·10^30 and -p+8.
			Public: []string{
				new(big.Int).Sub(big.NewInt(5), new(big.Int).Mul(pow10(10), bigIntP())).String(),
				"4",
			},
			Private: []string{
				"7",
				new(big.Int).Add(big.NewInt(8), new(big.Int).Mul(pow10(30), bigIntP())).String(),
				new(big.Int).Sub(big.NewInt(29), bigIntP()).String(),
			},
		},
	}
	for i, w := range unsat {
		res, err := s.CheckInput("cong", 1, artifact.Hash, w)
		if err != nil {
			t.Fatalf("unsatisfying case %d returned a call error: %v", i, err)
		}
		if res.Satisfied || res.FirstFailure != 2 || res.Hash != artifact.Hash {
			t.Fatalf("congruent unsatisfying case %d changed the verdict: %+v", i, res)
		}
	}
}

func bigIntP() *big.Int { return big.NewInt(2147483647) }

func pow10(n int) *big.Int {
	return new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(n)), nil)
}

// TestRepeatedWiresAndCancellingCoefficients checks that duplicate wire
// references are really summed (merged) and that coefficients that cancel to
// zero behave as the zero linear combination — including the discriminating
// case where one side cancels to zero but the other side still makes the
// equation false. Modulus 11 keeps the modular bookkeeping transparent.
func TestRepeatedWiresAndCancellingCoefficients(t *testing.T) {
	// Four constraints, all sharing wires w1 (public) and w2 (private):
	//	C1: (3·w1 + 8·w1) · 1 = w2     -> 11·w1 = 0, i.e. w2 must be 0.
	//	C2: (2·w1 + 3·w1 + 6·w1) · w2 = (5·w1 + 6·w1)·w2  -> 11·w1·w2 = 0.
	//	C3: (5·w2 - 5·w2) · w1 = w2    -> left cancels to 0; holds iff w2 = 0.
	//	C4: (7 + 4)·w1 · 1 = (10+1)·w1 -> 11·w1 = 0 for every w1.
	def := `{"modulus":"11","constraints":[
		{"a":[{"wire":1,"coeff":"3"},{"wire":1,"coeff":"8"}],"b":[{"wire":0,"coeff":"1"}],"c":[{"wire":2,"coeff":"1"}]},
		{"a":[{"wire":1,"coeff":"2"},{"wire":1,"coeff":"3"},{"wire":1,"coeff":"6"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":1,"coeff":"5"},{"wire":1,"coeff":"6"},{"wire":2,"coeff":"1"}]},
		{"a":[{"wire":2,"coeff":"5"},{"wire":2,"coeff":"-5"}],"b":[{"wire":1,"coeff":"1"}],"c":[{"wire":2,"coeff":"1"}]},
		{"a":[{"wire":1,"coeff":"7"},{"wire":1,"coeff":"4"}],"b":[{"wire":0,"coeff":"1"}],"c":[{"wire":1,"coeff":"10"},{"wire":1,"coeff":"1"}]}]}`
	s, artifact := regressionCircuit(t, "dup", 1, 1, 1, def)

	// Satisfying: w1 = 9 (any value works for the coefficient-cancellation
	// constraints), w2 = 0. C1: 0·1 = 0; C2: 0·0 = 0; C3: 0·9 = 0;
	// C4: 0·1 = 0. The non-zero public value proves cancellation does the
	// work rather than every input being zero.
	good := Witness{Public: []string{"9"}, Private: []string{"0"}}
	assertSatisfied(t, s, "dup", 1, artifact.Hash, good)

	// w2 = 4: C1 fails (0 != 4) — the repeated-wire sum on side a really
	// merged to zero and the c side still demands zero.
	failsC1 := Witness{Public: []string{"9"}, Private: []string{"4"}}
	assertUnsatisfied(t, s, "dup", 1, artifact.Hash, failsC1, 1)

	// The key cancellation discriminator: w1 = 0 makes C1 and C2 hold even
	// with w2 = 4 (0 = 0 and 0·4 = 0), and C4 trivially holds, but C3's left
	// side cancels to zero by construction while its right side is 4: the
	// equation is false and must be recognised as such — a zero side is not
	// a wildcard. This fails at C3, proving the earlier two genuinely held.
	discriminator := Witness{Public: []string{"0"}, Private: []string{"4"}}
	assertUnsatisfied(t, s, "dup", 1, artifact.Hash, discriminator, 3)

	// Congruent representation of the satisfying witness: 9 = -2 mod 11,
	// and 0 + 11·10^18 reduces to 0; verdict and first_failure must match.
	congruent := Witness{
		Public:  []string{"-2"},
		Private: []string{"11000000000000000000"},
	}
	assertSatisfied(t, s, "dup", 1, artifact.Hash, congruent)

	// Sanity on the merged canonical form: coefficients 3 and 8 on the same
	// wire of C1 must have merged (11 ≡ 0) and been dropped, so the stored
	// definition does not retain two terms.
	got, err := s.GetDefinition("dup", 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Constraints[0].A) != 0 {
		t.Fatalf("C1 side a should have merged to zero and been dropped, got %+v", got.Constraints[0].A)
	}
	// But the cancellation is per-side: C3 side c with w2 coeff 1 survives.
	if len(got.Constraints[2].C) != 1 {
		t.Fatalf("C3 side c must keep its single non-cancelling term, got %+v", got.Constraints[2].C)
	}
}

