// definition, replacing inputs with other legal decimal representations that
// differ by an integer multiple of the modulus leaves both the satisfaction
// state and the first-failure position unchanged. The alternatives are
// negative and far longer than machine integers.
func TestMaxPrimeCongruentRepresentationsAgree(t *testing.T) {
	// Reuse the ordering circuit: it has multiple constraints so the
	// first-failure index is meaningful in the unsatisfied variants too.
	def := `{"modulus":"` + regressionMaxPrime + `","constraints":[
		{"a":[{"wire":0,"coeff":"-1"},{"wire":1,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"1"},{"wire":3,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"198"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":2,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"-1"},{"wire":4,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"45"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":5,"coeff":"1"}],
		 "b":[{"wire":0,"coeff":"1"}],
		 "c":[{"wire":0,"coeff":"30"}]}]}`
	s, artifact := regressionCircuit(t, "cong", 1, 2, 3, def)

	// Satisfying family: (5,4,7,2,29) rewritten with values congruent mod p.
	// x_big = (p-5) + p·10^24 happens to equal 5's family-mate only after
	// reduction... here each listed value is congruent to the corresponding
	// base value: 5 + p·10^20, 4 - p·10^12, 7 + p, 2 - 2p, 29 + p·10^8.
	cases := []Witness{
		{Public: []string{"5", "4"}, Private: []string{"7", "2", "29"}},
		{
			Public: []string{
				new(big.Int).Add(big.NewInt(5), new(big.Int).Mul(pow10(20), bigIntP())).String(),
				new(big.Int).Sub(big.NewInt(4), new(big.Int).Mul(pow10(12), bigIntP())).String(),
			},
			Private: []string{
				new(big.Int).Add(big.NewInt(7), bigIntP()).String(),
				new(big.Int).Sub(big.NewInt(2), new(big.Int).Add(bigIntP(), bigIntP())).String(),
				new(big.Int).Add(big.NewInt(29), new(big.Int).Mul(pow10(8), bigIntP())).String(),
			},
		},
	}
	for i, w := range cases {
		res, err := s.CheckInput("cong", 1, artifact.Hash, w)
		if err != nil {
			t.Fatalf("satisfying case %d: %v", i, err)
		}
		if !res.Satisfied || res.FirstFailure != 0 || res.Hash != artifact.Hash {
			t.Fatalf("congruent satisfying case %d changed the verdict: %+v", i, res)
		}
	}

	// Unsatisfying family: the base (5,4,7,8,29) fails at C2. Two
	// congruent rewrites (one 40-digit positive, one huge negative) must
	// keep the identical first-failure position.
	unsat := []Witness{
		{Public: []string{"5", "4"}, Private: []string{"7", "8", "29"}},
		{ // y4 = (p-7+... ) must equal 8 + kp; use 8 + p·10^30 and -p+8.
			Public: []string{
				new(big.Int).Sub(big.NewInt(5), new(big.Int).Mul(pow10(10), bigIntP())).String(),
				"4",
			},
			Private: []string{
				"7",
				new(big.Int).Add(big.NewInt(8), new(big.Int).Mul(pow10(30), bigIntP())).String(),
				new(big.Int).Sub(big.NewInt(29), bigIntP()).String(),
			},
		},
	}
	for i, w := range unsat {
		res, err := s.CheckInput("cong", 1, artifact.Hash, w)
		if err != nil {
			t.Fatalf("unsatisfying case %d returned a call error: %v", i, err)
		}
		if res.Satisfied || res.FirstFailure != 2 || res.Hash != artifact.Hash {
			t.Fatalf("congruent unsatisfying case %d changed the verdict: %+v", i, res)
		}
	}
}

func bigIntP() *big.Int { return big.NewInt(2147483647) }

func pow10(n int) *big.Int {
	return new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(n)), nil)
}

// TestRepeatedWiresAndCancellingCoefficients checks that duplicate wire
// references are really summed (merged) and that coefficients that cancel to
// zero behave as the zero linear combination — including the discriminating
// case where one side cancels to zero but the other side still makes the
// equation false. Modulus 11 keeps the modular bookkeeping transparent.
func TestRepeatedWiresAndCancellingCoefficients(t *testing.T) {
	// Four constraints, all sharing wires w1 (public) and w2 (private):
	//	C1: (3·w1 + 8·w1) · 1 = w2     -> 11·w1 = 0, i.e. w2 must be 0.
	//	C2: (2·w1 + 3·w1 + 6·w1) · w2 = (5·w1 + 6·w1)·w2  -> 11·w1·w2 = 0.
	//	C3: (5·w2 - 5·w2) · w1 = w2    -> left cancels to 0; holds iff w2 = 0.
	//	C4: (7 + 4)·w1 · 1 = (10+1)·w1 -> 11·w1 = 0 for every w1.
	def := `{"modulus":"11","constraints":[
		{"a":[{"wire":1,"coeff":"3"},{"wire":1,"coeff":"8"}],"b":[{"wire":0,"coeff":"1"}],"c":[{"wire":2,"coeff":"1"}]},
		{"a":[{"wire":1,"coeff":"2"},{"wire":1,"coeff":"3"},{"wire":1,"coeff":"6"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":1,"coeff":"5"},{"wire":1,"coeff":"6"},{"wire":2,"coeff":"1"}]},
		{"a":[{"wire":2,"coeff":"5"},{"wire":2,"coeff":"-5"}],"b":[{"wire":1,"coeff":"1"}],"c":[{"wire":2,"coeff":"1"}]},
		{"a":[{"wire":1,"coeff":"7"},{"wire":1,"coeff":"4"}],"b":[{"wire":0,"coeff":"1"}],"c":[{"wire":1,"coeff":"10"},{"wire":1,"coeff":"1"}]}]}`
	s, artifact := regressionCircuit(t, "dup", 1, 1, 1, def)

	// Satisfying: w1 = 9 (any value works for the coefficient-cancellation
	// constraints), w2 = 0. C1: 0·1 = 0; C2: 0·0 = 0; C3: 0·9 = 0;
	// C4: 0·1 = 0. The non-zero public value proves cancellation does the
	// work rather than every input being zero.
	good := Witness{Public: []string{"9"}, Private: []string{"0"}}
	assertSatisfied(t, s, "dup", 1, artifact.Hash, good)

	// w2 = 4: C1 fails (0 != 4) — the repeated-wire sum on side a really
	// merged to zero and the c side still demands zero.
	failsC1 := Witness{Public: []string{"9"}, Private: []string{"4"}}
	assertUnsatisfied(t, s, "dup", 1, artifact.Hash, failsC1, 1)

	// The key cancellation discriminator: w1 = 0 makes C1 and C2 hold even
	// with w2 = 4 (0 = 0 and 0·4 = 0), and C4 trivially holds, but C3's left
	// side cancels to zero by construction while its right side is 4: the
	// equation is false and must be recognised as such — a zero side is not
	// a wildcard. This fails at C3, proving the earlier two genuinely held.
	discriminator := Witness{Public: []string{"0"}, Private: []string{"4"}}
	assertUnsatisfied(t, s, "dup", 1, artifact.Hash, discriminator, 3)

	// Congruent representation of the satisfying witness: 9 = -2 mod 11,
	// and 0 + 11·10^18 reduces to 0; verdict and first_failure must match.
	congruent := Witness{
		Public:  []string{"-2"},
		Private: []string{"11000000000000000000"},
	}
	assertSatisfied(t, s, "dup", 1, artifact.Hash, congruent)

	// Sanity on the merged canonical form: coefficients 3 and 8 on the same
	// wire of C1 must have merged (11 ≡ 0) and been dropped, so the stored
	// definition does not retain two terms.
	got, err := s.GetDefinition("dup", 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Constraints[0].A) != 0 {
		t.Fatalf("C1 side a should have merged to zero and been dropped, got %+v", got.Constraints[0].A)
	}
	// But the cancellation is per-side: C3 side c with w2 coeff 1 survives.
	if len(got.Constraints[2].C) != 1 {
		t.Fatalf("C3 side c must keep its single non-cancelling term, got %+v", got.Constraints[2].C)
	}
}

